function iylaAtmosphere(){x.save();for(const e of iyla.explosions){const p=e.t/e.life;if(p<.15&&!iyla2026.seen.has(e.seed)){iyla2026.seen.add(e.seed);for(let n=0;n<Math.min(18,5+e.power*4);n++){const a=rnd(0,TAU),v=rnd(20,120)*e.power;iyla2026.smoke.push({x:e.x,y:e.y,vx:Math.cos(a)*v*.22,vy:Math.sin(a)*v*.22-15,r:rnd(8,22)*e.power,life:rnd(.8,1.8),max:1.8,color:e.color});iyla2026.debris.push({x:e.x,y:e.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:rnd(2,6),life:rnd(.35,1.1),spin:rnd(-8,8),a:0})}}}const dt=Math.min(.033,iyla.frame||.016);for(let i=iyla2026.smoke.length-1;i>=0;i--){const s=iyla2026.smoke[i];s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.r+=9*dt;if(s.life<=0){iyla2026.smoke.splice(i,1);continue}x.globalAlpha=clamp(s.life/s.max,0,.22);x.fillStyle=s.color;x.beginPath();x.arc(s.x,s.y,s.r,0,TAU);x.fill()}for(let i=iyla2026.debris.length-1;i>=0;i--){const d=iyla2026.debris[i];d.life-=dt;d.x+=d.vx*dt;d.y+=d.vy*dt;d.vy+=160*dt;d.a+=d.spin*dt;if(d.life<=0){iyla2026.debris.splice(i,1);continue}x.save();x.translate(d.x,d.y);x.rotate(d.a);x.fillStyle='#ffc96b';x.fillRect(-d.r,-d.r*.35,d.r*2,d.r*.7);x.restore()}x.restore()}
